"use server";

import { flutterwaveRequest } from "./client";

export interface InitializePaymentParams {
  /** Unique transaction reference — generate one if not provided. */
  txRef: string;
  amount: number;
  currency?: string;
  email: string;
  name?: string;
  phoneNumber?: string;
  redirectUrl?: string;
  metadata?: Record<string, unknown>;
}

export interface InitializePaymentResult {
  status: string;
  message: string;
  data: {
    link: string;
  };
}

export interface VerifyTransactionResult {
  status: string;
  message: string;
  data: {
    id: number;
    tx_ref: string;
    amount: number;
    currency: string;
    status: "successful" | "failed" | "pending";
    customer: { email: string; name: string };
    created_at: string;
  };
}

export async function initializePayment(
  params: InitializePaymentParams,
): Promise<InitializePaymentResult> {
  return flutterwaveRequest<InitializePaymentResult>("POST", "/payments", {
    tx_ref: params.txRef,
    amount: params.amount,
    currency: params.currency ?? "NGN",
    redirect_url: params.redirectUrl,
    customer: {
      email: params.email,
      name: params.name,
      phonenumber: params.phoneNumber,
    },
    meta: params.metadata,
  });
}

export async function verifyTransaction(
  id: number,
): Promise<VerifyTransactionResult> {
  return flutterwaveRequest<VerifyTransactionResult>(
    "GET",
    `/transactions/${id}/verify`,
  );
}

