import crypto from "crypto";
import { adapter } from "./adapter";

export interface FlutterwaveWebhookEvent {
  event: string;
  data: {
    id: number;
    tx_ref: string;
    amount: number;
    currency: string;
    status: string;
    customer: { email: string; id: number };
    created_at: string;
  };
}

export interface PaymentData {
  txRef: string;
  transactionId: number;
  amount: number;
  currency: string;
  status: string;
  email: string;
  paidAt: string;
}

// Flutterwave sends the webhook secret verbatim as the `verif-hash` header.
// Timing-safe comparison prevents oracle attacks even on a plain string check.
export function verifyWebhookSignature(
  signature: string,
  secret: string,
): boolean {
  const a = Buffer.from(signature, "utf8");
  const b = Buffer.from(secret, "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

export async function handleFlutterwaveEvent(
  event: FlutterwaveWebhookEvent,
) {
  switch (event.event) {
    case "charge.completed": {
      // Flutterwave may re-deliver webhooks — adapter should upsert on
      // `txRef` (unique constraint) to stay idempotent across retries.
      await adapter.recordPayment({
        txRef: event.data.tx_ref,
        transactionId: event.data.id,
        amount: event.data.amount,
        currency: event.data.currency,
        status: event.data.status,
        email: event.data.customer.email,
        paidAt: event.data.created_at,
      });
      break;
    }
    default:
      console.log(`Unhandled Flutterwave event: ${event.event}`);
  }
}

