"use client";

import { useFlutterwave, closePaymentModal } from "@flutterwave/flutterwave-react-v3";

if (!process.env.NEXT_PUBLIC_FLW_PUBLIC_KEY) {
  throw new Error("NEXT_PUBLIC_FLW_PUBLIC_KEY is missing from .env.local");
}

interface CheckoutButtonProps {
  /** Amount in the smallest currency unit (kobo for NGN, pesewas for GHS, cents for USD). */
  amount: number;
  currency?: string;
  email: string;
  name?: string;
  phone?: string;
  metadata?: Record<string, unknown>;
  label?: string;
  onSuccess?: (data: { transaction_id: number; tx_ref: string; status: string }) => void;
  onClose?: () => void;
}

export function FlutterwaveCheckoutButton({
  amount,
  currency = "NGN",
  email,
  name,
  phone,
  metadata,
  label = "Pay Now",
  onSuccess,
  onClose,
}: CheckoutButtonProps) {
  const txRef = `flw-${Date.now()}-${Math.random().toString(36).slice(2)}`;

  const config = {
    public_key: process.env.NEXT_PUBLIC_FLW_PUBLIC_KEY!,
    tx_ref: txRef,
    amount,
    currency,
    payment_options: "card,banktransfer,ussd",
    customer: {
      email,
      name: name ?? "",
      phone_number: phone ?? "",
    },
    meta: metadata,
    customizations: {
      title: "Payment",
      description: "Complete your payment",
    },
  };

  const handleFlutterPayment = useFlutterwave(config);

  return (
    <button
      type="button"
      onClick={() =>
        handleFlutterPayment({
          callback: (data) => {
            closePaymentModal();
            onSuccess?.({
              transaction_id: data.transaction_id,
              tx_ref: data.tx_ref,
              status: data.status,
            });
          },
          onClose: () => {
            onClose?.();
          },
        })
      }
    >
      {label}
    </button>
  );
}

