import { headers } from "next/headers";
import { handleFlutterwaveEvent, verifyWebhookSignature } from "@/infra/flutterwave/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const signature = headersList.get("verif-hash");

  if (!signature) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.FLW_WEBHOOK_SECRET) {
    console.error("[flutterwave webhook] FLW_WEBHOOK_SECRET is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (!verifyWebhookSignature(signature, process.env.FLW_WEBHOOK_SECRET)) {
    console.error("[flutterwave webhook] Invalid verif-hash signature");
    return new Response("Unauthorized", { status: 401 });
  }

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  let event;
  try {
    event = JSON.parse(body);
  } catch (err: unknown) {
    console.error("[flutterwave webhook] malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so Flutterwave retries — distinct from 4xx above.
  try {
    await handleFlutterwaveEvent(event);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[flutterwave webhook] handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}

