import { db } from "@/lib/db";
import type { PaymentData } from "./webhooks";

// Idempotent upsert keyed on `txRef` — webhook retries won't duplicate rows.
export const adapter = {
  recordPayment: async (data: PaymentData) => {
    await db.payment.upsert({
      where: { txRef: data.txRef },
      update: {
        transactionId: data.transactionId,
        amount: data.amount,
        currency: data.currency,
        status: data.status,
        email: data.email,
        paidAt: new Date(data.paidAt),
      },
      create: {
        txRef: data.txRef,
        transactionId: data.transactionId,
        amount: data.amount,
        currency: data.currency,
        status: data.status,
        email: data.email,
        paidAt: new Date(data.paidAt),
      },
    });
  },
};

